{
  bool carrier;
  char ipv4[INET_ADDRSTRLEN];
  bool keep_apply_feedback;

  if (g_status.state == VG_NETWORK_APPLYING)
    {
      return;
    }

  carrier = vg_network_query_carrier();
  vg_network_query_ipv4(ipv4, sizeof(ipv4));

  g_status.carrier = carrier;
  g_status.mode = g_saved_config.mode;
  strlcpy(g_status.ipv4, ipv4, sizeof(g_status.ipv4));

  /* Unrecoverable apply failure: keep ERROR, but still refresh carrier/IP. */

  if (g_status.state == VG_NETWORK_ERROR)
    {
      return;
    }

  /* Recoverable apply feedback (last_error != 0) must not block operational
   * state updates, and must not sticky-trap the home/network summary forever.
   */

  keep_apply_feedback = g_status.last_error != 0;

  if (!carrier)
    {
      g_status.state = VG_NETWORK_DOWN;
      if (!keep_apply_feedback)
        {
          vg_network_set_message_locked("无链路");
        }
    }
