    {
      g_status.state = VG_NETWORK_ADDRESSING;
      if (!keep_apply_feedback)
        {
          vg_network_set_message_locked(
            g_saved_config.mode == VG_NETWORK_MODE_DHCP ?
            "正在获取地址" : "等待地址");
        }
    }
  else
    {
      g_status.state = VG_NETWORK_ONLINE;
